function SectionHeader({ eyebrow, title, subtitle, action }) {
  return (
    <div style={{
      display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between',
      gap: 16, marginBottom: 20, flexWrap: 'wrap',
    }}>
      <div>
        {eyebrow && (
          <div style={{
            fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase',
            color: 'var(--franchise-subtext)', marginBottom: 6,
          }}>{eyebrow}</div>
        )}
        <h2 style={{
          fontFamily: 'Fraunces, serif', fontWeight: 700,
          fontSize: 26, lineHeight: 1.05, letterSpacing: '-0.015em',
          color: 'var(--franchise-text)', margin: 0,
        }}>{title}</h2>
        {subtitle && (
          <div style={{ fontSize: 13, color: 'var(--franchise-subtext)',
                        marginTop: 6, fontWeight: 500 }}>{subtitle}</div>
        )}
      </div>
      {action}
    </div>
  );
}

