function PlayoffOutlook({ oddsData, primaryColor, playoffOdds }) {
  const currentIdx = oddsData.length - 1;
  const weekAgo = oddsData[currentIdx - 1].odds;
  const weekDelta = playoffOdds - weekAgo;
  return (
    <div className="mf-section-card">
      <SectionHeader eyebrow="Postseason Odds" title="Playoff Outlook" />
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, marginBottom: 10 }}>
        <div style={{
          fontFamily: 'Fraunces, serif', fontWeight: 700,
          fontSize: 48, lineHeight: 1,
          color: 'var(--franchise-primary-deep)', letterSpacing: '-0.03em',
        }}>{playoffOdds}%</div>
        <div style={{
          fontSize: 12, fontWeight: 700,
          color: weekDelta >= 0 ? '#15803d' : '#b91c1c',
          display: 'flex', alignItems: 'center', gap: 2,
        }}>
          {weekDelta >= 0 ? '↑' : '↓'} {Math.abs(weekDelta)} pts
          <span style={{ color: '#a39d90', fontWeight: 500, marginLeft: 4 }}>this week</span>
        </div>
      </div>
      <div style={{ width: '100%', height: 110 }}>
        <ResponsiveContainer>
          <AreaChart data={oddsData} margin={{ top: 4, right: 4, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="mfPoGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={primaryColor} stopOpacity={0.3} />
                <stop offset="100%" stopColor={primaryColor} stopOpacity={0} />
              </linearGradient>
            </defs>
            <YAxis domain={[0, 100]} hide />
            <XAxis dataKey="week" hide />
            <Area type="monotone" dataKey="odds"
                  stroke={primaryColor} strokeWidth={2} fill="url(#mfPoGradient)"
                  dot={(props) => {
                    const { cx, cy, index } = props;
                    const isCurrent = index === currentIdx;
                    return (
                      <circle key={`po-dot-${index}`}
                              cx={cx} cy={cy}
                              r={isCurrent ? 4 : 2.5}
                              fill={primaryColor}
                              stroke={isCurrent ? '#ffffff' : 'none'}
                              strokeWidth={isCurrent ? 2 : 0} />
                    );
                  }}
                  activeDot={false} />
          </AreaChart>
        </ResponsiveContainer>
      </div>
      <div style={{
        display: 'flex', justifyContent: 'space-between',
        fontSize: 10, fontWeight: 600, color: '#a39d90',
        letterSpacing: '0.06em', textTransform: 'uppercase',
        padding: '0 4px',
      }}>
        <span>Preseason</span>
        <span>Week 7</span>
      </div>
      <div style={{
        marginTop: 16, padding: '12px 14px',
        background: 'rgba(232,193,104,0.1)',
        borderLeft: '3px solid var(--franchise-accent)',
        borderRadius: '0 6px 6px 0',
        fontSize: 12, lineHeight: 1.5,
      }}>
        <span style={{ fontWeight: 700, color: 'var(--franchise-primary-deep)' }}>On track for a top seed.</span>
        <span style={{ color: '#56514a' }}> A win this week would lock in playoffs and push you toward the #1 bye.</span>
      </div>
    </div>
  );
}

// ============================================================================
// PHASE INDICATOR
// ============================================================================
// ============================================================================
// ROSTER — the primary action surface of the page
// ============================================================================
// Interaction model:
//   • Tap a player's POSITION PILL to select them for a swap. Eligible
//     counterparts on the opposite side of the roster get a "swap target"
//     ring. Tap one of them to swap. Tap the selected pill again to cancel.
//   • Tap a player's NAME (or the rest of the row) to open the detail modal
//     with season stats, recent game log, and this week's matchup note.
// No "Save Changes" button — swaps are immediate/implicit.
function RosterRow({
  player, isBench, isSelected, isEligibleSwap,
  onPillClick, onRowClick,
}) {
  const isInjured = player.injured;
  const displayPos = isBench ? player.nflPos : player.slot;
  const pillColors = POSITION_COLORS[displayPos] || POSITION_COLORS.BN;

  // Defensive rank color-coding
  const rank = player.oppDefRank;
  let rankColor = '#7a7468';
  if (rank != null) {
    if (rank <= 10) rankColor = '#b91c1c';       // tough matchup
    else if (rank >= 23) rankColor = '#15803d';  // soft matchup
  }

  const rowClasses = [
    'mf-roster-row',
    isBench ? 'mf-roster-row-bench' : '',
    isSelected ? 'mf-roster-row-selected' : '',
    isEligibleSwap ? 'mf-roster-row-eligible' : '',
    isInjured ? 'mf-roster-row-injured' : '',
  ].filter(Boolean).join(' ');

  return (
    <div className={rowClasses}>
      {/* Position pill — clickable for swap */}
      <button
        className="mf-roster-pill-btn"
        onClick={(e) => { e.stopPropagation(); onPillClick(player); }}
        aria-label={isSelected ? `Cancel swap for ${player.name}` : `Swap ${player.name}`}
      >
        <span className="mf-roster-pos" style={{
          background: pillColors.bg,
          color: pillColors.text,
        }}>
          {displayPos}
        </span>
      </button>

      {/* Team-colored silhouette avatar (placeholder for real NFL headshot) */}
      <PlayerAvatar player={player} size={32} />

      {/* Clickable name area — opens detail modal */}
      <button
        className="mf-roster-name-btn"
        onClick={() => onRowClick(player)}
        aria-label={`View ${player.name} details`}
      >
        <div className="mf-roster-name">{player.name}</div>
        <div className="mf-roster-subname">
          <span>{player.nflTeam} {player.homeAway} {player.opponent}</span>
          {rank != null && (
            <>
              <span style={{ color: '#cfc8bc', margin: '0 5px' }}>·</span>
              <span style={{ color: rankColor, fontWeight: 600 }}>
                {ordinal(rank).replace(/^/, rank + '')} vs {player.nflPos}
              </span>
            </>
          )}
        </div>
      </button>

      {/* Game-time label */}
      <div className="mf-roster-game-block">
        <span className="mf-roster-game-label"
              style={{
                color: isInjured ? '#b91c1c' : '#7a7468',
                background: isInjured ? 'rgba(185,28,28,0.1)' : 'transparent',
              }}>
          {player.gameLabel}
        </span>
      </div>

      {/* Projected score */}
      <div className="mf-roster-score-block">
        <div className="mf-roster-score" style={{
          color: isInjured ? '#b91c1c' : '#22201c',
          opacity: isInjured ? 0.5 : 1,
        }}>
          {isInjured ? '—' : player.projected.toFixed(1)}
        </div>
        <div className="mf-roster-score-sub">proj</div>
      </div>
    </div>
  );
}

function Roster({ initialRoster, isPremium }) {
  const [rosterState, setRosterState] = useState(initialRoster);
  const [selectedId, setSelectedId] = useState(null);
  const [benchExpanded, setBenchExpanded] = useState(true);
  const [detailPlayer, setDetailPlayer] = useState(null);

  const allPlayers = useMemo(
    () => [...rosterState.starters, ...rosterState.bench],
    [rosterState]
  );
  const selectedPlayer = useMemo(
    () => allPlayers.find(p => p.id === selectedId) || null,
    [selectedId, allPlayers]
  );
  const selectedIsStarter = useMemo(
    () => rosterState.starters.some(p => p.id === selectedId),
    [selectedId, rosterState]
  );

  function isEligibleSwap(otherPlayer) {
    if (!selectedPlayer) return false;
    if (otherPlayer.id === selectedPlayer.id) return false;
    if (otherPlayer.injured) return false;
    const otherIsStarter = rosterState.starters.some(p => p.id === otherPlayer.id);
    if (selectedIsStarter === otherIsStarter) return false;
    const starter   = selectedIsStarter ? selectedPlayer : otherPlayer;
    const benchSide = selectedIsStarter ? otherPlayer    : selectedPlayer;
    const eligiblePositions = SLOT_ELIGIBILITY[starter.slot] || [];
    return eligiblePositions.includes(benchSide.nflPos);
  }

  function executeSwap(a, b) {
    const aIsStarter = rosterState.starters.some(p => p.id === a.id);
    const starter   = aIsStarter ? a : b;
    const benchSide = aIsStarter ? b : a;
    const starterIdx = rosterState.starters.findIndex(p => p.id === starter.id);
    const benchIdx   = rosterState.bench.findIndex(p => p.id === benchSide.id);
    const newStarters = [...rosterState.starters];
    const newBench    = [...rosterState.bench];
    newStarters[starterIdx] = { ...benchSide, slot: starter.slot };
    const { slot, ...starterAsBench } = starter;
    newBench[benchIdx] = starterAsBench;
    setRosterState({ starters: newStarters, bench: newBench });
  }

  function handlePillClick(player) {
    if (player.injured) return;
    if (!selectedId) { setSelectedId(player.id); return; }
    if (selectedId === player.id) { setSelectedId(null); return; }
    if (isEligibleSwap(player)) {
      executeSwap(selectedPlayer, player);
      setSelectedId(null);
    } else {
      setSelectedId(player.id);
    }
  }

  const projectedTotal = rosterState.starters.reduce((a, p) => a + p.projected, 0);

  return (
    <div className="mf-section-card mf-roster-card">
      {/* Branded header in Premium, plain header in Free.
          Premium uses the same painted-turf language as the Hero but at a
          section-header scale — primary action surfaces get identity
          treatment; analytical surfaces below stay clean. */}
      {isPremium ? (
        <div className="mf-roster-branded-header">
          <div className="mf-roster-branded-stripes" />
          <div className="mf-roster-branded-lighting" />
          <div className="mf-roster-branded-hairline-top" />
          <div className="mf-roster-branded-hairline-bottom" />
          <div className="mf-roster-branded-inner">
            <div className="mf-roster-branded-eyebrow">Week 7 · Set Your Lineup</div>
            <h2 className="mf-roster-branded-title">
              Active <span className="mf-roster-branded-italic">Roster</span>
            </h2>
            <div className="mf-roster-branded-subtitle">
              Lineup locks Sunday 1:00 PM ET. Tap a position to swap — changes save automatically.
            </div>
          </div>
        </div>
      ) : (
        <div className="mf-roster-plain-header">
          <SectionHeader
            eyebrow="Week 7 · Set Your Lineup"
            title="Active Roster"
            subtitle="Lineup locks Sunday 1:00 PM ET. Tap a position to swap — changes save automatically."
          />
        </div>
      )}

      <div className="mf-roster-body">
        {selectedPlayer && (
          <div className="mf-swap-banner">
            <span className="mf-swap-banner-label">Swapping</span>
            <span className="mf-swap-banner-name">{selectedPlayer.name}</span>
            <span className="mf-swap-banner-hint">
              · Tap an eligible {selectedIsStarter ? 'bench' : 'starter'} to complete · or tap the pill again to cancel
            </span>
            <button
              className="mf-swap-banner-cancel"
              onClick={() => setSelectedId(null)}
              aria-label="Cancel swap"
            >✕</button>
          </div>
        )}

        <div className="mf-roster">
          <div className="mf-roster-subheader">Starters</div>
          <div className="mf-roster-rows">
            {rosterState.starters.map(p => (
              <RosterRow
                key={p.id}
                player={p}
                isBench={false}
                isSelected={selectedId === p.id}
                isEligibleSwap={selectedPlayer != null && selectedId !== p.id && isEligibleSwap(p)}
                onPillClick={handlePillClick}
                onRowClick={setDetailPlayer}
              />
            ))}
          </div>

          <div className="mf-roster-totals">
            <div className="mf-roster-totals-label">Starters projected</div>
            <div className="mf-roster-totals-breakdown">
              <span style={{ fontFamily: 'Fraunces, serif', fontWeight: 700, fontSize: 20,
                             color: 'var(--franchise-primary)', letterSpacing: '-0.02em' }}>
                {projectedTotal.toFixed(1)}
              </span>
              <span style={{ color: '#7a7468', marginLeft: 6, fontSize: 12 }}>pts</span>
            </div>
          </div>

          <button className="mf-bench-toggle"
                  onClick={() => setBenchExpanded(!benchExpanded)}>
            <span style={{
              fontSize: 10, fontWeight: 700, letterSpacing: '0.18em',
              textTransform: 'uppercase',
            }}>
              {benchExpanded ? '▾' : '▸'}  Bench · {rosterState.bench.length} players
            </span>
          </button>
          {benchExpanded && (
            <div className="mf-roster-rows mf-roster-bench">
              {rosterState.bench.map(p => (
                <RosterRow
                  key={p.id}
                  player={p}
                  isBench={true}
                  isSelected={selectedId === p.id}
                  isEligibleSwap={selectedPlayer != null && selectedId !== p.id && isEligibleSwap(p)}
                  onPillClick={handlePillClick}
                  onRowClick={setDetailPlayer}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {detailPlayer && (
        <PlayerDetailModal
          player={detailPlayer}
          onClose={() => setDetailPlayer(null)}
        />
      )}
    </div>
  );
}

// ============================================================================
// PLAYER DETAIL MODAL — opens when user taps a player's name
// ============================================================================
// Shows season stats, last-3-game average, recent game log (4 weeks),
// and a human-readable matchup note for this week. This is the surface
// where rich player context lives — keeping it out of the roster row
// prevents the row from getting cramped and preserves mobile readability.
function PlayerDetailModal({ player, onClose }) {
  const posColors = POSITION_COLORS[player.nflPos] || POSITION_COLORS.BN;
  const rank = player.oppDefRank;
  let rankColor = '#7a7468';
  let rankLabel = null;
  if (rank != null) {
    if (rank <= 10)      { rankColor = '#b91c1c'; rankLabel = 'Tough'; }
    else if (rank <= 22) { rankColor = '#7a7468'; rankLabel = 'Neutral'; }
    else                 { rankColor = '#15803d'; rankLabel = 'Favorable'; }
  }

  return (
    <div className="mf-modal-backdrop" onClick={onClose}>
      <div className="mf-modal-card" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="mf-modal-header" style={{
          background: `linear-gradient(135deg, ${posColors.bg} 0%, ${posColors.bg}dd 100%)`,
          color: posColors.text,
        }}>
          <div className="mf-modal-header-stripes" />
          <button
            className="mf-modal-close"
            onClick={onClose}
            aria-label="Close"
            style={{ color: posColors.text }}
          >✕</button>
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: 16 }}>
            <PlayerAvatar player={player} size={68} />
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{
                fontSize: 11, fontWeight: 800, letterSpacing: '0.14em',
                textTransform: 'uppercase', opacity: 0.85, marginBottom: 6,
              }}>
                {player.nflPos} · {player.nflTeam}
              </div>
              <h3 style={{
                fontFamily: 'Fraunces, serif', fontWeight: 700,
                fontSize: 26, lineHeight: 1, letterSpacing: '-0.02em',
                margin: 0, color: posColors.text,
              }}>
                {player.name}
              </h3>
              <div style={{
                fontSize: 13, opacity: 0.85, marginTop: 7, fontWeight: 500,
              }}>
                {player.nflTeam} {player.homeAway} {player.opponent} · {player.gameLabel}
              </div>
            </div>
          </div>
        </div>

        {/* Stats grid */}
        <div className="mf-modal-stats">
          <div className="mf-modal-stat">
            <div className="mf-modal-stat-label">Season Avg</div>
            <div className="mf-modal-stat-value">{player.stats.seasonAvg.toFixed(1)}</div>
          </div>
          <div className="mf-modal-stat">
            <div className="mf-modal-stat-label">Last 3 Avg</div>
            <div className="mf-modal-stat-value">{player.stats.last3Avg.toFixed(1)}</div>
          </div>
          <div className="mf-modal-stat">
            <div className="mf-modal-stat-label">Week 7 Proj</div>
            <div className="mf-modal-stat-value" style={{ color: 'var(--franchise-primary)' }}>
              {player.projected.toFixed(1)}
            </div>
          </div>
          {rank != null && (
            <div className="mf-modal-stat">
              <div className="mf-modal-stat-label">Matchup</div>
              <div className="mf-modal-stat-value" style={{ color: rankColor, fontSize: 17 }}>
                {rankLabel}
              </div>
              <div style={{ fontSize: 10, color: '#a39d90', marginTop: 2,
                            fontWeight: 600, letterSpacing: '0.06em' }}>
                {player.opponent} ranks {ordinal(rank).replace(/^/, rank + '')} vs {player.nflPos}
              </div>
            </div>
          )}
        </div>

        {/* Recent games */}
        <div className="mf-modal-section">
          <div className="mf-modal-section-label">Recent Games</div>
          <div className="mf-modal-games">
            {player.stats.recentGames.map((g, i) => (
              <div key={i} className="mf-modal-game-row">
                <span className="mf-modal-game-week">Week {g.week}</span>
                <span className="mf-modal-game-opp">{g.opp}</span>
                <span className="mf-modal-game-pts">{g.pts.toFixed(1)}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Matchup note */}
        <div className="mf-modal-section">
          <div className="mf-modal-section-label">This Week</div>
          <p className="mf-modal-note">{player.stats.matchupNote}</p>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
// FRANCHISE INTELLIGENCE — AI tools panel (the core Phase 3 monetization)
// ============================================================================
// Each tool renders as an IntelligenceCard. In Free mode, each card shows:
//   (1) title + individual tool price
//   (2) a specific teaser (not generic "upgrade") with a glimpse of value
//   (3) a clear unlock CTA
// In Premium mode, each card shows the fully actionable recommendation
// with real names, numbers, and contextual reasoning. Both states use the
// SAME card chrome — consistency conveys "this is a real tool that
// activates when you unlock it," not a shell with different content.
function IntelligenceCard({
  icon, title, subtitle, price, isPremium,
  teaser, children, actions,
}) {
  const Icon = icon;
  return (
    <div className={`mf-intel-card ${isPremium ? 'mf-intel-card-unlocked' : 'mf-intel-card-locked'}`}>
      <div className="mf-intel-header">
        <div className="mf-intel-header-left">
          <div className="mf-intel-icon">
            <Icon size={15} strokeWidth={2.25} />
          </div>
          <div>
            <div className="mf-intel-title">{title}</div>
            <div className="mf-intel-subtitle">{subtitle}</div>
          </div>
        </div>
        <div className="mf-intel-status">
          {isPremium ? (
            <span className="mf-intel-active">
              <span className="mf-intel-active-dot" />
              Active
            </span>
          ) : (
            <span className="mf-intel-price">{price}</span>
          )}
        </div>
      </div>
      <div className="mf-intel-body">
        {isPremium ? children : (
          <div className="mf-intel-teaser">
            <Lock size={12} strokeWidth={2.5} style={{ flexShrink: 0, opacity: 0.5 }} />
            <span>{teaser}</span>
          </div>
        )}
      </div>
      <div className="mf-intel-footer">
        {isPremium ? (
          <div className="mf-intel-actions">
            {actions.map((a, i) => (
              <button key={i} className={`mf-intel-btn ${a.primary ? 'mf-intel-btn-primary' : ''}`}>
                {a.label}
              </button>
            ))}
          </div>
        ) : (
          <button className="mf-intel-unlock-btn">
            Unlock · {price}
          </button>
        )}
      </div>
    </div>
  );
}

