// ============================================================================
// FRANCHISE LEGACY — the narrative/dynasty surface (Phase 4)
// ============================================================================
// Four sub-sections organized as:
//   1. CareerOverview  — branded identity moment + all-time stats
//   2. HeadToHead       — rivalry list with opponent-palette color strips
//   3. Achievements     — 8-badge grid (5 unlocked + 3 locked-with-progress)
//   4. ThisWeekInHistory — AI-narrated historical moments tied to current week
// This section creates switching costs for dynasty leagues — years of data
// aggregated into a narrative is the opposite of easily-replicable content.

const ACHIEVEMENT_ICON_MAP = {
  Trophy, Flame, Award, Zap, Crown, Sparkles, TrendingUp, Target,
};

function CareerOverviewCard({ isPremium }) {
  const statTiles = [
    { value: careerStats.championships,                 label: 'Championships',  context: careerStats.championshipYears.join(' · ') },
    { value: `${careerStats.allTime.w}-${careerStats.allTime.l}`, label: 'All-Time Record', context: `${careerStats.seasons} seasons · ${(careerStats.allTime.w / (careerStats.allTime.w + careerStats.allTime.l) * 100).toFixed(1)}% win` },
    { value: careerStats.playoffs,                      label: 'Playoff Berths', context: `${careerStats.playoffs} of ${careerStats.seasons} seasons` },
    { value: careerStats.highScore.toFixed(1),          label: 'High Score',     context: 'Week 14, 2021' },
    { value: `+${careerStats.biggestWin.toFixed(1)}`,   label: 'Biggest Win',    context: 'Week 7, 2019' },
  ];

  return (
    <div className="mf-section-card mf-legacy-card">
      {isPremium ? (
        <div className="mf-legacy-branded-header">
          <div className="mf-roster-branded-stripes" />
          <div className="mf-roster-branded-lighting" />
          <div className="mf-roster-branded-hairline-top" />
          <div className="mf-roster-branded-hairline-bottom" />
          <div className="mf-roster-branded-inner">
            <div className="mf-roster-branded-eyebrow">
              Est. {careerStats.firstYear} · {careerStats.seasons} Seasons
            </div>
            <h2 className="mf-roster-branded-title">
              Franchise <span className="mf-roster-branded-italic">Legacy</span>
            </h2>
            <div className="mf-roster-branded-subtitle">
              The Gridiron Syndicate's career story — every championship, every rival, every defining moment.
            </div>
          </div>
        </div>
      ) : (
        <div className="mf-roster-plain-header">
          <SectionHeader
            eyebrow={`Est. ${careerStats.firstYear} · ${careerStats.seasons} Seasons`}
            title="Franchise Legacy"
            subtitle="The Gridiron Syndicate's career story."
          />
        </div>
      )}

      <div className="mf-legacy-stats">
        {statTiles.map((t, i) => (
          <div key={i} className="mf-legacy-stat-tile">
            <div className="mf-legacy-stat-value">{t.value}</div>
            <div className="mf-legacy-stat-label">{t.label}</div>
            <div className="mf-legacy-stat-context">{t.context}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

function HeadToHeadCard() {
  return (
    <div className="mf-section-card">
      <SectionHeader
        eyebrow="League Rivalries"
        title="Head-to-Head"
        subtitle={`All-time records vs each league opponent, sorted by games played.`}
      />
      <div className="mf-rivalry-list">
        {rivalries.map((r, i) => {
          const palette = LEAGUE_PALETTES[r.team] || '#6B7280';
          const winPct = (r.record.w / (r.record.w + r.record.l)) * 100;
          return (
            <div key={i} className="mf-rivalry-row">
              <div className="mf-rivalry-strip" style={{ background: palette }} />
              <div className="mf-rivalry-main">
                <div className="mf-rivalry-team">{r.team}</div>
                <div className="mf-rivalry-note">{r.note}</div>
              </div>
              <div className="mf-rivalry-record">
                <div className="mf-rivalry-record-num">
                  {r.record.w}<span style={{ color: '#a39d90', fontWeight: 500 }}>-</span>{r.record.l}
                </div>
                <div className="mf-rivalry-record-meta">
                  {r.games} games · {winPct.toFixed(0)}%
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function AchievementsCard() {
  return (
    <div className="mf-section-card">
      <SectionHeader
        eyebrow="Career Milestones"
        title="Achievements"
        subtitle={`${achievements.filter(a => a.unlocked).length} of ${achievements.length} unlocked.`}
      />
      <div className="mf-achievements-grid">
        {achievements.map((a) => {
          const Icon = ACHIEVEMENT_ICON_MAP[a.icon] || Trophy;
          return (
            <div key={a.id} className={`mf-achievement ${a.unlocked ? 'mf-achievement-unlocked' : 'mf-achievement-locked'}`}>
              <div className="mf-achievement-icon-wrap">
                {a.unlocked ? (
                  <Icon size={22} strokeWidth={2.25} />
                ) : (
                  <>
                    <Icon size={22} strokeWidth={2.25} style={{ opacity: 0.35 }} />
                    <div className="mf-achievement-lock-overlay">
                      <Lock size={12} strokeWidth={2.5} />
                    </div>
                  </>
                )}
              </div>
              <div className="mf-achievement-title">{a.title}</div>
              <div className="mf-achievement-desc">{a.description}</div>
              <div className="mf-achievement-meta">
                {a.unlocked ? (
                  <span className="mf-achievement-year">{a.year}</span>
                ) : (
                  <span className="mf-achievement-progress">{a.progress}</span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ThisWeekInHistoryCard() {
  return (
    <div className="mf-section-card">
      <SectionHeader
        eyebrow="AI-Narrated · Week 7"
        title="This Week in Syndicate History"
        subtitle="Three defining moments from previous Week 7s in franchise history."
      />
      <div className="mf-history-moments">
        {historyMoments.map((m, i) => (
          <div key={i} className="mf-history-moment">
            <div className="mf-history-year-badge">{m.year}</div>
            <div className="mf-history-body">
              <div className="mf-history-title">{m.title}</div>
              <div className="mf-history-stat-row">
                <div className="mf-history-stat">{m.stat}</div>
                <div className="mf-history-stat-label">{m.statLabel}</div>
              </div>
              <p className="mf-history-summary">{m.summary}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function FranchiseLegacy({ isPremium }) {
  return (
    <>
      <CareerOverviewCard isPremium={isPremium} />
      <HeadToHeadCard />
      <AchievementsCard />
      <ThisWeekInHistoryCard />
    </>
  );
}

function PhaseIndicator() {
  const phases = [
    { num: 1, name: 'Franchise Identity',    status: 'done' },
    { num: 2, name: 'Season Overview',       status: 'done' },
    { num: 3, name: 'Roster & Intelligence', status: 'done' },
    { num: 4, name: 'Legacy & History',      status: 'active' },
  ];
  return (
    <div style={{ maxWidth: 1400, margin: '0 auto', padding: '48px 32px', textAlign: 'center' }}>
      <div style={{ borderTop: '1px solid rgba(0,0,0,0.08)', paddingTop: 36 }}>
        <div style={{
          fontSize: 10, fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase',
          color: '#a39d90', marginBottom: 16,
        }}>My Franchise · Build Progress</div>
        <div style={{ display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap' }}>
          {phases.map(p => {
            const isActive = p.status === 'active';
            const isDone   = p.status === 'done';
            return (
              <div key={p.num} style={{
                display: 'flex', alignItems: 'center', gap: 8,
                padding: '8px 14px', borderRadius: 999,
                background: isActive ? '#22201c' : (isDone ? 'rgba(22, 101, 52, 0.1)' : 'rgba(0,0,0,0.04)'),
                color:      isActive ? '#f7f3ea' : (isDone ? '#15803d' : '#7a7468'),
                fontSize: 12, fontWeight: 600,
              }}>
                <span style={{
                  fontFamily: 'Fraunces, serif', fontStyle: 'italic', fontWeight: 700,
                  opacity: 0.7,
                }}>{isDone ? '✓' : p.num}</span>
                <span>{p.name}</span>
                {isActive && <span style={{ opacity: 0.7 }}>· now</span>}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

